pc.script.createLoadingScreen(function (app) {
	var showSplash = function () {
		// splash wrapper
		var wrapper = document.createElement('div');
		wrapper.id = 'application-splash-wrapper';
		document.body.appendChild(wrapper);
		wrapper.setAttribute('draggable', false);
		wrapper.ondragstart = function (event) {
			event.preventDefault();
		};
		// splash
		var splash = document.createElement('div');
		splash.id = 'application-splash';
		wrapper.appendChild(splash);
		splash.style.display = 'none';
		splash.addEventListener('dragstart', function (event) {
			event.preventDefault();
		});

		var logo = document.createElement('img');
		logo.src = 'data:image/png;base64,';
		logo.setAttribute('draggable', false);
		logo.ondragstart = function (event) {
			event.preventDefault();
		};
		splash.appendChild(logo);
		logo.onload = function () {
			splash.style.display = 'block';
		};

		var spinner = document.createElement('div');
		spinner.id = 'loading-spinner';
		splash.appendChild(spinner);

		var container = document.createElement('div');
		container.id = 'progress-bar-container';
		wrapper.appendChild(container);

		var bar = document.createElement('div');
		bar.id = 'progress-bar';
		container.appendChild(bar);

		var percentage = document.createElement('div');
		percentage.id = 'progress-percentage';
		percentage.textContent = "0%";
		container.appendChild(percentage);
	};

	var hideSplash = function () {
		var splash = document.getElementById('application-splash-wrapper');
		if (splash) {
			splash.style.transition = 'opacity 0.5s ease'; // Add smooth fade transition
			splash.style.opacity = '0'; // Trigger fade-out

			// Remove the element after the transition completes
			setTimeout(function () {
				splash.parentElement.removeChild(splash);
			}, 500); // Match the duration of the transition
		}
	};
	var setProgress = function (value) {
		var bar = document.getElementById('progress-bar');
		var percentage = document.getElementById('progress-percentage');
		if (bar) {
			value = Math.min(1, Math.max(0, value));
			bar.style.width = value * 100 + '%';
			if (percentage) {
				percentage.textContent = Math.round(value * 100) + '%'; // Update the percentage text
			}
		}
	};

	var createCss = function () {
		var css = [
	`
	body {
	    margin: 0;
	    overflow: hidden;
	    height: 100%;
	}

	#application-splash-wrapper {
	    position: fixed;
	    top: 0;
	    left: 0;
	    height: 100%;
	    width: 100%;
        --s: 1105px; /* control the size*/
        --c1: #373e3e;
        --c2: #343b3b;
        --c3: #394141;
        background:
          conic-gradient(from  15deg at 86.6%,
            var(--c3) 25%,var(--c2) 0 150deg,#0000 0),
          conic-gradient(from -75deg at 50% 13.39%,
            var(--c1) 60deg,var(--c3) 0 150deg,
            var(--c2) 0 210deg,#0000 0),
          conic-gradient(from 15deg at 36.6% 63.4%,
           var(--c1) 60deg,var(--c3) 0 150deg,
           var(--c1) 0 210deg,var(--c2) 0 75%,var(--c3) 0);
        background-size: var(--s) var(--s);
	    display: flex; /* Flexbox to easily center items */
	    justify-content: center;
	    align-items: center;
	}
	
	#application-splash {
	    position: relative;
	    text-align: center;
	}

	#application-splash img {
	    display: block;
		pointer-events: none;
		user-select: none;
	    max-width: 100%;
	    max-height: 100%;
	    object-fit: cover;
	}

	#progress-bar-container {
	    position: fixed;
	    bottom: 75px;
	    left: 50%;
	    transform: translateX(-50%);
	    height: 30px;
	    width: 100%;
	    max-width: 480px;
	    border-radius: 10px;
	    background-color: #290000;
	    z-index: 2;
	}

	#progress-bar {
	    width: 0%;
	    height: 100%;
	    border-radius: 10px;
	    background-color: #e00604;
    	filter: drop-shadow(5px 5px 10px rgba(0, 0, 0, 0.5));
	}

	#progress-percentage {
	    position: absolute;
	    top: 50%;
	    left: 50%;
	    transform: translate(-50%, -50%);
	    font-family: Tahoma, sans-serif;
	    font-size: 14px;
	    font-weight: bold;
	    color: #ffffff;
	    z-index: 3;
	}

	#loading-spinner {
	    position: absolute;
	    top: 50%;
	    left: 50%;
	    transform: translate(-50%, -50%);
	    width: 20px;
	    height: 20px;
	    border: 13px solid #353a3d;
	    border-top: 13px solid #6b6965;
	    border-radius: 50%;
	    animation: spin 1s linear infinite;
	}

	@keyframes spin {
	    0% {
	        transform: translate(-50%, -50%) rotate(0deg);
	    }
	    100% {
	        transform: translate(-50%, -50%) rotate(360deg);
	    }
	}

	@media (max-width: 480px) {
	    #progress-bar-container {
	        width: 200px; /* Adjust for smaller screens */
	    }
	}
	`
		];

		var style = document.createElement('style');
		style.type = 'text/css';
		if (style.styleSheet) {
			style.styleSheet.cssText = css;
		} else {
			style.appendChild(document.createTextNode(css));
		}

		document.head.appendChild(style);
	};

	createCss();
	showSplash();

	app.on('preload:end', function () {
		app.off('preload:progress');
	});
	app.on('preload:progress', setProgress);
	app.on('start', hideSplash);

});